Az ÖSSZES hibát megkeresed a kódban Az elsőtől az utolsóig minden karaktert átnézel Csak a konkrét pontos hibákat mindet írod Listába  majd ha megtalaltad az osszes hibat teljes kódot kijavítva vissza küldöd. minden egyes karaktert leírsz, nem rövidítesz. minden hibát kijavítasz. egy fájl marad. ne írj semmi mást csak a teljes kódot es kommentek nem lehetnek benne! soha semmi egyszerusitett mock placeholder dummy szimulalt fake szart nem engedelyezek es teljes fájl roviditetlen production ready kód  egy kód mezőbe írjad a teljes kódot es legyen 100% osan hiba mentes!  es arra törekedj hogy mindenben a kód a lehető legfejlettebb legjobb teljesítményű leggyorsabb és mindenben a legjobb legyen! 



module main

import net
import net.http
import json
import os
import time
import io

struct Message {
	role string
	content string
}

struct ChatRequest {
	messages []Message
	model string = 'gptoss120b'
	stream bool
	max_completion_tokens int = 65536
	temperature f64 = 0.04
	top_p f64 = 0.01
}

fn handle_request(mut conn net.TcpConn, api_key string) {
	mut reader := io.new_buffered_reader(reader: conn)
	first_line := reader.read_line() or { return }
	parts := first_line.split(' ')
	if parts.len < 3 {
		return
	}

	method := parts[0]
	path := parts[1]
	mut content_length := 0
	mut headers := map[string]string{}
	for {
		line := reader.read_line() or { break }
		trimmed_line := line.trim_space()
		if trimmed_line == '' {
			break
		}

		if !trimmed_line.contains(':') {
			continue
		}

		idx := trimmed_line.index(':') or { continue }
		key_part := trimmed_line[..idx].trim_space().to_lower()
		value_part := trimmed_line[idx+1..].trim_space()
		headers[key_part] = value_part
		if key_part == 'contentlength' {
			content_length = value_part.int()
		}
	}

	mut body := ''
	if content_length > 0 {
		mut buf := []u8{len: content_length}
		reader.read(mut buf) or { return }
		body = buf.bytestr()
	}

	if path == '/' || path == '/index.html' {
		serve_file(mut conn, 'index.html')
	} else if path == '/api/health' {
		handle_health(mut conn, api_key)
	} else if path == '/api/models' {
		handle_models(mut conn)
	} else if path == '/api/chat' {
		if method == 'POST' {
			handle_chat(mut conn, body, api_key)
		} else if method == 'OPTIONS' {
			send_cors_preflight(mut conn)
		} else {
			send_404(mut conn)
		}
	} else {
		send_404(mut conn)
	}
}

fn send_cors_headers(mut conn net.TcpConn) {
	conn.write_string('AccessControlAllowOrigin: \r\n') or {}
	conn.write_string('AccessControlAllowMethods: GET, POST, OPTIONS\r\n') or {}
	conn.write_string('AccessControlAllowHeaders: ContentType\r\n') or {}
}

fn send_cors_preflight(mut conn net.TcpConn) {
	conn.write_string('HTTP/1.1 204 No Content\r\n') or {}
	send_cors_headers(mut conn)
	conn.write_string('\r\n') or {}
}

fn serve_file(mut conn net.TcpConn, filename string) {
	content := os.read_file(filename) or {
		send_404(mut conn)
		return
	}

	conn.write_string('HTTP/1.1 200 OK\r\n') or {}
	conn.write_string('ContentType: text/html\r\n') or {}
	conn.write_string('CacheControl: nocache\r\n') or {}
	send_cors_headers(mut conn)
	conn.write_string('ContentLength: ${content.len}\r\n') or {}
	conn.write_string('\r\n') or {}
	conn.write_string(content) or {}
}

fn send_404(mut conn net.TcpConn) {
	msg := '404 Not Found'
	conn.write_string('HTTP/1.1 404 Not Found\r\n') or {}
	conn.write_string('ContentType: text/plain\r\n') or {}
	send_cors_headers(mut conn)
	conn.write_string('ContentLength: ${msg.len}\r\n') or {}
	conn.write_string('\r\n') or {}
	conn.write_string(msg) or {}
}

fn handle_health(mut conn net.TcpConn, api_key string) {
	current_time := time.now().unix()
	api_configured := if api_key != '' { 'true' } else { 'false' }
	response := '{"status":"healthy","api_configured":${api_configured},"timestamp":${current_time},"version":"1.0.0"}'
	conn.write_string('HTTP/1.1 200 OK\r\n') or {}
	conn.write_string('ContentType: application/json\r\n') or {}
	send_cors_headers(mut conn)
	conn.write_string('ContentLength: ${response.len}\r\n') or {}
	conn.write_string('\r\n') or {}
	conn.write_string(response) or {}
}

fn handle_models(mut conn net.TcpConn) {
	models := ['gptoss120b', 'llama3.18b', 'llama3.170b', 'llama3.370b', 'llama3.18binstruct']
	response := json.encode(models)
	conn.write_string('HTTP/1.1 200 OK\r\n') or {}
	conn.write_string('ContentType: application/json\r\n') or {}
	send_cors_headers(mut conn)
	conn.write_string('ContentLength: ${response.len}\r\n') or {}
	conn.write_string('\r\n') or {}
	conn.write_string(response) or {}
}

fn handle_chat(mut conn net.TcpConn, body string, api_key string) {
	if api_key == '' {
		error_msg := '{"error":"CEREBRAS_API_KEY not configured"}'
		conn.write_string('HTTP/1.1 500 Internal Server Error\r\n') or {}
		conn.write_string('ContentType: application/json\r\n') or {}
		send_cors_headers(mut conn)
		conn.write_string('ContentLength: ${error_msg.len}\r\n') or {}
		conn.write_string('\r\n') or {}
		conn.write_string(error_msg) or {}
		return
	}

	req := json.decode(ChatRequest, body) or {
		error_msg := '{"error":"Invalid request format"}'
		conn.write_string('HTTP/1.1 400 Bad Request\r\n') or {}
		conn.write_string('ContentType: application/json\r\n') or {}
		send_cors_headers(mut conn)
		conn.write_string('ContentLength: ${error_msg.len}\r\n') or {}
		conn.write_string('\r\n') or {}
		conn.write_string(error_msg) or {}
		return
	}

	mut header := http.new_header()
	header.add(.authorization, 'Bearer ${api_key}')
	header.add(.content_type, 'application/json')
	config := http.FetchConfig{
		method: .post
		url: ''
		data: body
		header: header
	}

	response := http.fetch(config) or {
		error_msg := '{"error":"Failed to connect to Cerebras API"}'
		conn.write_string('HTTP/1.1 500 Internal Server Error\r\n') or {}
		conn.write_string('ContentType: application/json\r\n') or {}
		send_cors_headers(mut conn)
		conn.write_string('ContentLength: ${error_msg.len}\r\n') or {}
		conn.write_string('\r\n') or {}
		conn.write_string(error_msg) or {}
		return
	}

	if req.stream {
		conn.write_string('HTTP/1.1 200 OK\r\n') or {}
		conn.write_string('ContentType: text/eventstream\r\n') or {}
		conn.write_string('CacheControl: nocache\r\n') or {}
		conn.write_string('Connection: keepalive\r\n') or {}
		send_cors_headers(mut conn)
		conn.write_string('\r\n') or {}
		lines := response.body.split('\n')
		for line in lines {
			trimmed := line.trim_space()
			if trimmed.starts_with('data: ') {
				conn.write_string('${trimmed}\n\n') or { break }
				if trimmed == 'data: [DONE]' {
					break
				}
			}
		}
	} else {
		conn.write_string('HTTP/1.1 ${response.status_code} ${response.status_msg}\r\n') or {}
		conn.write_string('ContentType: application/json\r\n') or {}
		send_cors_headers(mut conn)
		conn.write_string('ContentLength: ${response.body.len}\r\n') or {}
		conn.write_string('\r\n') or {}
		conn.write_string(response.body) or {}
	}
}

fn main() {
	api_key := os.getenv('CEREBRAS_API_KEY')
	println('═══════════════════════════════════════')
	println(' JADED AI Platform  V Backend')
	println('═══════════════════════════════════════')
	println('')
	if api_key == '' {
		println('⚠️  WARNING: CEREBRAS_API_KEY not set')
		println('   Server will start but API calls will fail')
		println('')
	} else {
		println('✓ CEREBRAS_API_KEY configured')
		println('✓ API key length: ${api_key.len} characters')
		println('')
	}

	println('🚀 Starting server on ')
	println('📡 Endpoints:')
	println('   GET  /  Frontend UI')
	println('   POST /api/chat  Chat completions')
	println('   GET  /api/models  Available models')
	println('   GET  /api/health  Health check')
	println('')
	println('Press Ctrl+C to stop')
	println('═══════════════════════════════════════')
	println('')

	mut listener := net.listen_tcp(.ip, ':5000') or {
		eprintln('Failed to start server: ${err}')
		return
	}

	for {
		mut conn := listener.accept() or {
			eprintln('Failed to accept connection: ${err}')
			continue
		}
		spawn handle_request(mut conn, api_key)
	}
}

