module main

import net
import net.http
import json
import os
import time
import strings

struct Message {
	role string
	content string
}

struct ChatRequest {
	messages []Message
	model string = 'gpt-oss-120b'
	stream bool = false
	max_completion_tokens int = 65536
	temperature f64 = 0.04
	top_p f64 = 0.01
}

fn parse_http_request(data string) ?(string, string, map[string]string, string) {
	lines := data.split('\r\n')
	if lines.len < 1 {
		return error('empty request')
	}

	first_line_parts := lines[0].split(' ')
	if first_line_parts.len < 3 {
		return error('invalid request line')
	}

	method := first_line_parts[0]
	path := first_line_parts[1]
	mut headers := map[string]string{}
	mut body_start := 0

	for i := 1; i < lines.len; i++ {
		line := lines[i]
		if line == '' {
			body_start = i + 1
			break
		}

		colon_pos := line.index(':')
		if colon_pos != -1 {
			key := line[..colon_pos].trim_space().to_lower()
			value := line[colon_pos + 1..].trim_space()
			headers[key] = value
		}
	}

	body := if body_start > 0 && body_start < lines.len {
		lines[body_start..].join('\r\n')
	} else {
		''
	}

	return method, path, headers, body
}

fn write_http_response(mut conn net.TcpConn, status_code int, status_text string, content_type string, cors bool, body string) ! {
	response_line := 'HTTP/1.1 ${status_code} ${status_text}\r\n'
	conn.write_string(response_line)!
	conn.write_string('Content-Type: ${content_type}\r\n')!
	if cors {
		conn.write_string('Access-Control-Allow-Origin: *\r\n')!
		conn.write_string('Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n')!
		conn.write_string('Access-Control-Allow-Headers: Content-Type\r\n')!
	}
	conn.write_string('Content-Length: ${body.len}\r\n')!
	conn.write_string('Connection: close\r\n')!
	conn.write_string('\r\n')!
	conn.write_string(body)!
}

fn serve_file(mut conn net.TcpConn, filename string) ! {
	content := os.read_file(filename)!
	write_http_response(mut conn, 200, 'OK', 'text/html; charset=utf-8', true, content)!
}

fn send_json_response(mut conn net.TcpConn, status_code int, status_text string, body string) ! {
	write_http_response(mut conn, status_code, status_text, 'application/json', true, body)!
}

fn send_error_json(mut conn net.TcpConn, status_code int, status_text string, error_msg string) ! {
	json_body := json.encode_pretty(map[string]string{'error': error_msg})
	send_json_response(mut conn, status_code, status_text, json_body)!
}

fn handle_health(mut conn net.TcpConn, api_key string) ! {
	current_time := time.now().unix()
	api_configured := api_key != ''
	response_map := map[string]interface{}{
		'status': 'healthy'
		'api_configured': api_configured
		'timestamp': current_time
		'version': '1.0.0'
	}
	body := json.encode_pretty(response_map)
	send_json_response(mut conn, 200, 'OK', body)!
}

fn handle_models(mut conn net.TcpConn) ! {
	models := ['gpt-oss-120b', 'llama3.1-8b', 'llama3.1-70b', 'llama3.3-70b', 'llama-3.1-8b-instruct']
	body := json.encode_pretty(models)
	send_json_response(mut conn, 200, 'OK', body)!
}

fn handle_chat(mut conn net.TcpConn, body string, api_key string) ! {
	if api_key == '' {
		send_error_json(mut conn, 500, 'Internal Server Error', 'CEREBRAS_API_KEY not configured')!
		return
	}

	req := json.decode(ChatRequest, body) or {
		send_error_json(mut conn, 400, 'Bad Request', 'Invalid request format')!
		return
	}

	mut header := http.new_header()
	header.add(.authorization, 'Bearer ${api_key}')
	header.add(.content_type, 'application/json')

	config := http.FetchConfig{
		method: .post
		url: 'https://api.cerebras.ai/v1/chat/completions'
		data: body
		header: header
	}

	response := http.fetch(config) or {
		send_error_json(mut conn, 500, 'Internal Server Error', 'Failed to connect to Cerebras API')!
		return
	}

	if req.stream {
		write_http_response(mut conn, 200, 'OK', 'text/event-stream', true, '')!
		lines := response.body.split('\n')
		for line in lines {
			trimmed := line.trim_space()
			if trimmed.starts_with('data: ') {
				conn.write_string('${trimmed}\r\n\r\n')!
				if trimmed == 'data: [DONE]' {
					break
				}
			}
		}
	} else {
		write_http_response(mut conn, response.status_code, 'OK', 'application/json', true, response.body)!
	}
}

fn handle_client(mut conn net.TcpConn, api_key string) {
	defer {
		conn.close() or {}
	}

	conn.set_read_timeout(5 * time.second)
	conn.set_write_timeout(5 * time.second)

	mut request_data := ''
	mut buf := []u8{len: 4096}

	for {
		n := conn.read(mut buf) or {
			break
		}
		if n == 0 {
			break
		}
		request_data += string(buf[..n])
		if request_data.len > 1048576 {
			break
		}
	}

	method, path, headers, request_body := parse_http_request(request_data) or {
		_ := send_error_json(mut conn, 400, 'Bad Request', 'Invalid HTTP request')
		return
	}

	if path == '/' || path == '/index.html' {
		serve_file(mut conn, 'index.html') or {
			_ := send_error_json(mut conn, 404, 'Not Found', 'File not found')
		}
	} else if path == '/api/health' {
		handle_health(mut conn, api_key) or {
			_ := send_error_json(mut conn, 500, 'Internal Server Error', 'Health check failed')
		}
	} else if path == '/api/models' {
		handle_models(mut conn) or {
			_ := send_error_json(mut conn, 500, 'Internal Server Error', 'Models retrieval failed')
		}
	} else if path == '/api/chat' {
		if method == 'POST' {
			handle_chat(mut conn, request_body, api_key) or {
				_ := send_error_json(mut conn, 500, 'Internal Server Error', 'Chat request failed')
			}
		} else if method == 'OPTIONS' {
			write_http_response(mut conn, 204, 'No Content', 'text/plain', true, '')!
		} else {
			send_error_json(mut conn, 405, 'Method Not Allowed', 'Method not allowed')!
		}
	} else {
		send_error_json(mut conn, 404, 'Not Found', 'Endpoint not found')!
	}
}

